const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=$('#app'),modal=$('#modal'),host=$('#scene');const arena=new Arena(host);let data,state=null,view='home',auto=false,sound=false,tutorial=0,selected='all',lastError='',playbackSpeed=1,closingMatch=null,pendingResult=null,replayEvent=null;const KEY='kangs-three-season-v2',TUTORIAL='kangs-three-tutorial-v2';
const routes=[['home','01','Program HQ'],['roster','02','Roster & rotation'],['practice','03','Practice planner'],['recruit','04','Tryouts'],['staff','05','Coach’s office'],['game','06','Game day'],['locker','07','Locker room'],['season','08','Season journal'],['data','09','Real Kangs data']];
