const micon=k=>`<span class="mouse-icon">${svg(MOUSE[k])}</span>`;
const NAV_ICONS={home:'<path d="M4 11l8-6.5 8 6.5"/><path d="M6 9.8V19h12V9.8M10 19v-5h4v5"/>',roster:'<circle cx="9" cy="8" r="3"/><path d="M3.5 19c.6-3.3 2.7-5 5.5-5s4.9 1.7 5.5 5"/><circle cx="17" cy="9" r="2.4"/><path d="M15.8 14.2c2.4.1 4 1.6 4.7 4.8"/>',practice:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="4"/><circle cx="12" cy="12" r=".6"/>',recruit:'<circle cx="10" cy="8" r="3.2"/><path d="M4 19c.6-3.4 2.9-5.2 6-5.2 1.3 0 2.4.3 3.4.9"/><path d="M18 13v6M15 16h6"/>',staff:'<rect x="4" y="6" width="16" height="13" rx="2"/><path d="M9 6V4.5h6V6M4 11.5h16"/>',game:'<circle cx="12" cy="12" r="8"/><path d="M4 12h16M12 4v16M6.3 6.3c2.6 2.6 2.6 8.8 0 11.4M17.7 6.3c-2.6 2.6-2.6 8.8 0 11.4"/>',locker:'<path d="M7 4h10v16H7z"/><path d="M12 4v16M9.5 10v2M14.5 10v2"/>',season:'<rect x="4" y="5" width="16" height="15" rx="2"/><path d="M8 3v4M16 3v4M4 10h16M8 14h3M8 17h6"/>',data:'<path d="M5 19V11M10 19V5M15 19v-6M20 19V8"/>'};
const PLAN_ICONS=['<circle cx="12" cy="12" r="8.5"/><circle cx="12" cy="12" r="4.5"/><circle cx="12" cy="12" r="1"/>','<path d="M12 3l7 3v5c0 4.5-3 8-7 10-4-2-7-5.5-7-10V6z"/><path d="M9 12l2 2 4-4"/>','<path d="M12 20s-7-4.4-7-10a4 4 0 017-2.6A4 4 0 0119 10c0 5.6-7 10-7 10z"/><path d="M8.5 11.5h2l1-2 1.5 4 1-2h1.5"/>','<path d="M4 6.5C7 5 9.5 5 12 6.5 14.5 5 17 5 20 6.5V19c-3-1.5-5.5-1.5-8 0-2.5-1.5-5-1.5-8 0z"/><path d="M12 6.5V19"/>','<path d="M4 17h16M6 17v-5a6 6 0 0112 0v5"/><path d="M12 4v2M8.5 20h7"/>'];
const crestText=n=>String(n||'').replace(/\(.*?\)/g,'').trim().split(/\s+/).filter(w=>/^[A-Za-z]/.test(w)).slice(0,2).map((w,i,a)=>a.length>1?w[0]:w.slice(0,3)).join('').toUpperCase()||'OPP';
const LOGO=`${import.meta.env.BASE_URL}images/kangs-logo.png`;
function tracker(){if(!state)return '';const n=state.schedule.length,done=state.results.length,cur=Math.min(n,closingMatch?state.results.at(-1).week+1:state.week+1);const ticks=state.schedule.map((g,i)=>{const r=state.results[i];const cls=r?(r.home>r.away?'w':'l'):i===state.week&&!state.finished?'next':'';return `<i class="${cls}" title="${r?`Game ${i+1}: ${r.home>r.away?'W':'L'} ${r.home}–${r.away}`:`Game ${i+1}`}"></i>`}).join('');
 return `<div class="game-tracker" aria-label="${state.finished?'Season complete':`Game ${cur} of ${n}`}"><div class="gt-top"><span>${state.finished?'SEASON COMPLETE':'GAME'}</span><b>${state.wins}–${state.losses}<em>RECORD</em></b></div><strong>${state.finished?n:cur}<small>/ ${n}</small></strong><div class="gt-ticks" style="--n:${n}">${ticks}</div><div class="gt-foot"><span>${done} played</span><span>${Math.max(0,n-done)} left</span></div></div>`;}
const btn=(text,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const pill=(text,cls='')=>`<span class="pill ${cls}">${text}</span>`;
const team=()=>E.teamFor(data,state?.difficulty??'elite');
const plan=()=>E.seasonPlan(state);
const f1=v=>v==null?'—':v.toFixed(1);
/* ESPN-style season leaders: category, player, per-game value. */
function leadersCard(){const L=E.leaders(state);const rows=[['ppg','Points Per Game'],['apg','Assists Per Game'],['rpg','Rebounds Per Game'],['bpg','Blocks Per Game'],['spg','Steals Per Game']];return `<section class="card leaders-card"><span class="eyebrow">SEASON LEADERS · ${esc(team().label.toUpperCase())}</span><ul class="leaders">${rows.map(([k,label])=>{const l=L[k];return `<li><b>${label}:</b> ${l?`<button class="leader-link" data-action="player" data-id="${l.id}">${esc(l.name)}</button> at ${l.value.toFixed(1)}`:'<span class="muted">appears after your first game</span>'}</li>`;}).join('')}</ul><small class="muted">${L.est?'2025–26 estimates from real team scoring. Your stats take over after the first game.':'Simulated statistics from your season.'}</small></section>`;}
/* ESPN-style box score: starters, bench, team totals. */
function boxTable(line,title='KANGS',compact=false){if(!line)return '';const rows=Object.entries(line).map(([id,l])=>({p:state.players.find(p=>p.id===+id),l})).filter(x=>x.l.min>0||x.l.fga||x.l.reb||x.l.ast||x.l.stl||x.l.blk||x.l.tov);if(!rows.length)return '';const tot=rows.reduce((t,{l})=>{for(const k of ['min','pts','reb','ast','stl','blk','fgm','fga','tpm','tpa','tov'])t[k]=(t[k]||0)+(l[k]||0);return t;},{});const cells=l=>compact?`<td><b>${l.pts}</b></td><td>${l.reb}</td><td>${l.ast}</td><td>${l.stl}</td><td>${l.blk}</td>`:`<td>${l.min??'—'}</td><td><b>${l.pts}</b></td><td>${l.fgm}-${l.fga}</td><td>${l.tpm}-${l.tpa}</td><td>${l.reb}</td><td>${l.ast}</td><td>${l.stl}</td><td>${l.blk}</td><td>${l.tov}</td>`;const heads=compact?['PTS','REB','AST','STL','BLK']:['MIN','PTS','FG','3PT','REB','AST','STL','BLK','TO'];const group=(name,list)=>list.length?`<tr class="box-group"><td>${name}</td>${heads.map(h=>`<td>${h}</td>`).join('')}</tr>${list.map(({p,l})=>`<tr><td class="box-player"><span class="box-name">${esc(p?.name??'Former roster player')}</span> <span class="box-pos">${p&&p.position[0]!=='N'?esc(p.position[0])+' ':''}#${p?.number??''}</span></td>${cells(l)}</tr>`).join('')}`:'';return `<div class="table-wrap box-score${compact?' compact':''}"><table><caption>${esc(title)}</caption><tbody>${group('STARTERS',rows.filter(x=>x.l.start))}${group('BENCH',rows.filter(x=>!x.l.start))}<tr class="box-total"><td class="box-player">TEAM</td>${cells(tot)}</tr></tbody></table></div>`;}
const TOAST_ICONS={success:'<path d="M5 12.5l4.2 4.2L19 7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7.5v.01"/>',error:'<path d="M12 3l9.5 17h-19z"/><path d="M12 10v4.5M12 17.5v.01"/>',warn:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6M12 16.5v.01"/>',staff:'<circle cx="12" cy="8" r="3.5"/><path d="M5 20c.8-4 3.6-6 7-6s6.2 2 7 6"/>',ball:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3v18M5.6 5.6c3 3 3 9.8 0 12.8M18.4 5.6c-3 3-3 9.8 0 12.8"/>',film:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M10 9.5l5 2.5-5 2.5z"/>'};
const TOAST_TITLES={success:'Done',info:'Heads up',error:'Can’t do that yet',warn:'Heads up'};
function notify(msg,opt={}){const box=$('#toast');if(!box)return;const type=opt.type||'info',ms=opt.ms??(type==='error'?6500:5200);const card=document.createElement('div');card.className=`toast-card ${type}`;card.setAttribute('role',type==='error'?'alert':'status');card.style.setProperty('--life',ms+'ms');
 card.innerHTML=`<span class="toast-icon" aria-hidden="true"><svg viewBox="0 0 24 24">${TOAST_ICONS[opt.icon]||TOAST_ICONS[type]}</svg></span><div class="toast-body"><b>${esc(opt.title||TOAST_TITLES[type])}</b><p>${esc(msg)}</p>${opt.chips?.length?`<div class="toast-chips">${opt.chips.map(c=>`<span class="${/^[−-]/.test(c)?'down':'up'}">${esc(c)}</span>`).join('')}</div>`:''}</div><button type="button" class="toast-close" aria-label="Dismiss notification"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button><i class="toast-timer" aria-hidden="true"></i>`;
 const kill=()=>{if(card.dataset.out)return;card.dataset.out=1;card.classList.add('out');setTimeout(()=>{card.remove();if(!box.children.length&&box.hidePopover&&box.matches(':popover-open'))box.hidePopover();},260);};
 let left=ms,start=Date.now(),timer=setTimeout(kill,left);card.addEventListener('mouseenter',()=>{clearTimeout(timer);left-=Date.now()-start;card.classList.add('hold');});card.addEventListener('mouseleave',()=>{start=Date.now();card.classList.remove('hold');timer=setTimeout(kill,Math.max(900,left));});card.querySelector('.toast-close').addEventListener('click',e=>{e.stopPropagation();clearTimeout(timer);kill();});
 box.prepend(card);[...box.children].slice(3).forEach(c=>c.remove());if(box.showPopover){try{if(box.matches(':popover-open'))box.hidePopover();box.showPopover();}catch{}}}
const signed=(n,unit)=>`${n>0?'+':'−'}${Math.abs(Math.round(n))} ${unit}`;
function actionToast(a,was){if(!state)return;const msg=state.log[0]?.text||'Saved.',chips=[];if(was){const dt=state.tokens-was.tokens,ds=state.actions-was.actions,dc=state.chemistry-was.chemistry;if(dt)chips.push(signed(dt,'tokens'));if(ds)chips.push(signed(ds,Math.abs(ds)===1?'prep slot':'prep slots'));if(dc)chips.push(signed(dc,'chemistry'));}
 if(a==='hire'){const c=E.staff.find(x=>x.key===state.assistant);return notify(c?`${c.name} joins your bench. ${c.detail[0].toUpperCase()+c.detail.slice(1)}.`:msg,{type:'success',icon:'staff',title:'Assistant coach hired',chips});}
 const map={train:['Practice complete','success','ball'],recruit:['Player signed','success','staff'],talk:['Team conversation','success','staff'],scout:['Opponent scouted','success','film'],release:['Player released','warn','staff'],dismiss:['Assistant dismissed','warn','staff']};const [title,type,icon]=map[a]||['Saved','success'];notify(msg,{title,type,icon,chips});}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{notify('Browser storage is unavailable. Export your season to keep progress.',{type:'warn',title:'Progress not saved'});}}
function tone(){if(!sound)return;try{const ctx=tone.ctx??=new AudioContext();ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(520,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(740,ctx.currentTime+.09);g.gain.setValueAtTime(.045,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.16);o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+.17);}catch{}}
function show(html){arena.paused=true;modal.innerHTML=`${btn('×','close','close','aria-label="Close dialog"')}<div class="modal-content">${html}</div>`;if(!modal.open)modal.showModal();}
function stage(cls=''){return `<div id="arena" class="${cls}" aria-label="Interactive 3D Kangs gym"><div class="arena-top">${pill('● KANGS FIELDHOUSE','live')}<span class="orbit-hint">${micon('drag')}Orbit${micon('scroll')}Zoom</span></div><div class="arena-bottom"><div><span class="eyebrow">KIRKLAND, WASHINGTON</span><h3 class="live-action">Our house. Your program.</h3></div><div class="camera-controls">${btn('Wide','camera',arena.mode==='broadcast'?'active':'','data-camera="broadcast"')}${btn('Courtside','camera',arena.mode==='court'?'active':'','data-camera="court"')}${btn('Follow','camera',arena.mode==='follow'?'active':'','data-camera="follow"')}${btn('Player view','camera',arena.mode==='player'?'active':'','data-camera="player" title="First-person view from the ball handler"')}</div></div></div>`;}
function meters(){return `<div class="metrics">${[['Record',`${state.wins}–${state.losses}`],['Program tokens',state.tokens.toLocaleString()],['Chemistry',`${Math.round(state.chemistry)}%`],['Fans',state.fans.toLocaleString()]].map(([a,b])=>`<div><span>${a}</span><strong>${b}</strong></div>`).join('')}</div>`;}
function header(kicker,title,description=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${tracker()}</div>`;}
function landing(){return `<main class="landing"><div class="landing-brand"><img class="brand-logo" src="${LOGO}" alt="" width="58" height="43"><div>LAKE WASHINGTON <span>BASKETBALL PROGRAM</span></div>${pill('A COACHING SIMULATION')}</div><div class="landing-content"><div class="landing-copy"><div class="eyebrow"><span class="line"></span> ALWAYS RISING.</div><h1>ROAD TO THE<br><em>CHAMPIONSHIP.</em></h1><p>Take the keys to the Kangs. Develop your players, make the hard calls, and write a different ending to a real season.</p><form id="start-form"><label for="coach">YOUR NAME, COACH</label><input id="coach" name="coach" maxlength="32" placeholder="Enter your name" required autocomplete="given-name"><div class="difficulty"><label for="difficulty">CHOOSE YOUR CHALLENGE</label><select id="difficulty" name="difficulty">${Object.entries(E.DIFFICULTIES).map(([k,d])=>`<option value="${k}" ${k==='standard'?'selected':''}>${d.label} · ${d.blurb}</option>`).join('')}</select></div><button class="primary launch" type="submit">Take over the Kangs <span>↗</span></button></form>${state?btn('Continue saved season →','continue','secondary wide'):''}<div class="landing-links">${btn('How to play','rules')}${btn('Credits & sources','credits')}${btn('Import season','import')}</div></div><div class="landing-visual">${stage('title-arena')}<div class="season-ticket"><span>${esc((data?.season??'2025–26').replace('–','—'))} / REIMAGINED</span><strong>THE ROAD<br>STARTS HERE.</strong><div>${data?.levels?`3 real Kangs teams · ${Object.values(data.levels).reduce((a,t)=>a+t.players.length,0)} players · ${Object.values(data.levels).reduce((a,t)=>a+t.games.length,0)} real matchups`:'Real Kangs rosters and matchups'}<br>Your decisions. Your results.</div></div></div></div><footer>ROAD TO THE CHAMPIONSHIP <span>INDEPENDENT STUDENT PROJECT · NOT SCHOOL-ENDORSED</span></footer></main>`;}
function home(){const opp=!state.finished?E.opponent(state):null,last=state.results.at(-1);return `${header('THE PROGRAM',`Welcome back, Coach ${esc(state.coach)}.`,state.finished?'Your season has its ending. Every decision helped write it.':'A championship is built long before tip-off.')}${meters()}<div class="hq-grid"><div>${stage()}<div class="quick-grid">${[['roster','SET THE FIVE','Build your rotation','↗'],['practice','PUT IN THE WORK',`${state.actions} preparation slots left`,'↗'],['staff','PEOPLE FIRST','Check in with your team','↗']].map(([v,a,b,c])=>`<button class="quick" data-view="${v}"><span>${a}</span><strong>${b}</strong><i>${c}</i></button>`).join('')}</div></div><aside class="right-rail"><section class="card next-game"><span class="eyebrow">${state.finished?'FINAL CHAPTER':'NEXT ON THE SCHEDULE'}</span>${state.finished?`<div class="matchup solo"><img src="${LOGO}" alt="Kangs"></div>`:`<div class="matchup"><img src="${LOGO}" alt="Kangs"><span>VS</span><b class="opp-crest">${esc(crestText(opp.opponent))}</b></div>`}<h2>${state.finished?(state.champion?'State champions.':'The season ends.'):esc(opp.opponent)}</h2><p>${state.finished?`${state.wins} wins. ${state.losses} losses. A program you built.`:`${esc(opp.date)} · ${esc(opp.venue)}`}</p>${btn(state.finished?'View season story':'Prepare for tip-off →',state.finished?'journal':'game','primary wide')}<small>${state.week>=plan().cut?`${plan().runName.toUpperCase()} · WIN OR GO HOME`:`${esc(team().label.toUpperCase())} · ONE SEASON. ONE CHAMPIONSHIP.`}</small></section>${leadersCard()}<section class="card"><span class="eyebrow">THE RIPPLE EFFECT</span><h3>Every choice travels.</h3><p>${esc(state.ripples[0]?.detail||'Practice, conversations and recovery change what happens on court. Your decision trail starts here.')}</p>${last?`<div class="mini-result">${last.won?'W':'L'} <strong>${last.home}–${last.away}</strong> ${esc(last.opponent)}</div>`:''}</section></aside></div>`;}
const SKIN=['#f1c7a3','#e0a87e','#c68a5e','#a86f45','#8a5634','#6b3f24','#4f2c19','#d9a07a'];
const HAIR=['#17110d','#2a1b12','#3d2616','#5b3a22','#8a5a2e','#b9874a','#d8b06a','#20180f'];
function avatar(p,size=48){const h=E.hashStr((p.originalName||p.name)+'|'+p.id),g=n=>(h>>>n),skin=SKIN[g(1)%SKIN.length],hair=HAIR[(g(4)+(SKIN.indexOf(skin)>3?0:2))%HAIR.length],style=(g(7)+p.id)%7,rx=21+g(11)%4,ry=26+g(13)%3,band=g(16)%6===0,beard=['Junior','Senior'].includes(p.year)&&g(18)%3===0,kit=state?.kit==='away'?['#f4effc','#562494']:state?.kit==='alternate'?['#191126','#e9b858']:['#6832ab','#ffffff'],uid='a'+h.toString(36)+p.id;
 const top=60-ry,shade=`color-mix(in srgb,${skin} 78%,#000)`;
 const hairSvg=[
  `<path d="M${60-rx} ${58-ry*.15}Q${60-rx} ${top-3} 60 ${top-3}Q${60+rx} ${top-3} ${60+rx} ${58-ry*.15}Q${60+rx-3} ${top+8} 60 ${top+6}Q${60-rx+3} ${top+8} ${60-rx} ${58-ry*.15}Z" fill="${hair}" opacity=".9"/>`,
  `<path d="M${60-rx+1} ${top+14}L${60-rx+2} ${top-14}Q60 ${top-20} ${60+rx-2} ${top-14}L${60+rx-1} ${top+14}Q60 ${top+4} ${60-rx+1} ${top+14}Z" fill="${hair}"/>`,
  `<g fill="${hair}">${[-16,-8,0,8,16,-12,-4,4,12].map((x,k)=>`<circle cx="${60+x}" cy="${top+(k<5?2:-5)}" r="${7.5}"/>`).join('')}</g>`,
  `<path d="M${60-rx} ${top+16}Q${60-rx} ${top-4} 60 ${top-4}Q${60+rx} ${top-4} ${60+rx} ${top+16}Q60 ${top+6} ${60-rx} ${top+16}Z" fill="${hair}"/><path d="M${60-rx+5} ${top+6}q6 -3 12 0t12 0t12 0" stroke="${skin}" stroke-opacity=".25" fill="none"/>`,
  `<path d="M${60-rx-1} ${top+20}Q${60-rx-2} ${top-6} 60 ${top-5}Q${60+rx+3} ${top-5} ${60+rx+1} ${top+18}Q${60+4} ${top+4} ${60-rx-1} ${top+20}Z" fill="${hair}"/>`,
  `<ellipse cx="60" cy="${top+10}" rx="${rx+9}" ry="${ry*.75}" fill="${hair}"/>`,
  `<path d="M${60-rx} ${top+18}Q${60-rx} ${top-2} 60 ${top-2}Q${60+rx} ${top-2} ${60+rx} ${top+18}L${60+rx-2} ${top+9}Q60 ${top+3} ${60-rx+2} ${top+9}Z" fill="${hair}"/><path d="M${60-rx+2} ${top+10}Q${60-rx-6} ${top+26} ${60-rx-1} ${top+34}M${60+rx-2} ${top+10}Q${60+rx+6} ${top+26} ${60+rx+1} ${top+34}" stroke="${hair}" stroke-width="5" fill="none" stroke-linecap="round"/>`][style];
 const behind=style===5?hairSvg:'',front=style===5?`<path d="M${60-rx+2} ${top+12}Q60 ${top+2} ${60+rx-2} ${top+12}" stroke="${hair}" stroke-width="6" fill="none"/>`:hairSvg;
 return `<svg class="avatar" width="${size}" height="${size*7/6}" viewBox="0 0 120 140" role="img" aria-label="${esc(p.name)} avatar"><defs><linearGradient id="${uid}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3b2160"/><stop offset="1" stop-color="#140c20"/></linearGradient></defs><rect width="120" height="140" rx="14" fill="url(#${uid})"/>${behind}
  <path d="M8 140C12 110 32 100 60 100S108 110 112 140Z" fill="${kit[0]}"/><path d="M44 101L60 118L76 101" fill="none" stroke="${kit[1]}" stroke-width="4"/><text x="60" y="137" text-anchor="middle" font-family="Barlow Condensed,Arial Narrow,sans-serif" font-weight="800" font-size="20" fill="${kit[1]}">${esc(p.number)}</text>
  <rect x="51" y="78" width="18" height="26" rx="6" fill="${shade}"/><ellipse cx="${60-rx}" cy="62" rx="4" ry="6" fill="${shade}"/><ellipse cx="${60+rx}" cy="62" rx="4" ry="6" fill="${shade}"/><ellipse cx="60" cy="60" rx="${rx}" ry="${ry}" fill="${skin}"/>${front}
  ${band?`<rect x="${60-rx}" y="${top+12}" width="${rx*2}" height="6" rx="3" fill="${kit[0]}" stroke="${kit[1]}" stroke-width="1"/>`:''}
  <path d="M${48-g(20)%3} 53q5 -${2+g(21)%2} 9 0M${63+g(20)%3} 53q5 -${2+g(21)%2} 9 0" stroke="${hair}" stroke-width="2.6" fill="none" stroke-linecap="round"/><ellipse cx="52.5" cy="60" rx="2.6" ry="3" fill="#1a1210"/><ellipse cx="67.5" cy="60" rx="2.6" ry="3" fill="#1a1210"/><path d="M60 62q-3 7 0 9" stroke="${shade}" stroke-width="2" fill="none" stroke-linecap="round"/><path d="M${53+g(22)%2} 77q7 ${3+g(23)%3} 14 0" stroke="#4a2a22" stroke-width="2.2" fill="none" stroke-linecap="round"/>
  ${beard?`<path d="M${60-rx+3} 66Q${60-rx+6} ${60+ry} 60 ${60+ry+1}Q${60+rx-6} ${60+ry} ${60+rx-3} 66" stroke="${hair}" stroke-width="3.2" fill="none" opacity=".85"/>`:''}</svg>`;}
let rosterSel=null;
const energyWord=e=>e>=80?'Fresh':e>=55?'Rested':e>=30?'Tired':'Exhausted',moraleWord=m=>m>=80?'Fired up':m>=60?'Content':m>=40?'Restless':'Unhappy';
function rosterCard(p){const r=E.ratings(p),b=E.bio(p),line=E.statLine(state,p),idx=state.players.indexOf(p),n=state.players.length;const ring=`conic-gradient(#b48aff ${r.ovr*3.6}deg,#ffffff14 0)`;
 const stars=k=>`<span class="stars" aria-label="${k} of 3 stars">${[1,2,3].map(i=>`<i class="${i<=k?'on':''}">★</i>`).join('')}</span>`;
 return `<section class="rv-hero" aria-live="polite"><button class="rv-arrow prev" data-action="rv-cycle" data-step="-1" aria-label="Previous player"><svg viewBox="0 0 24 24"><path d="M15 5l-7 7 7 7"/></svg></button>
 <div class="rv-portrait"><span class="rv-num" aria-hidden="true">${esc(p.number)}</span>${avatar(p,220)}<span class="rv-count">${idx+1} / ${n}</span></div>
 <div class="rv-main"><div class="rv-name"><span>${esc(p.name.split(' ').slice(0,-1).join(' '))}</span> <b>${esc(p.name.split(' ').slice(-1)[0])}</b><em>| ${esc(p.number)}</em></div>
  <div class="rv-row"><div class="rv-ovr"><span class="rv-tag">OVERALL</span><div class="ovr-ring" style="background:${ring}"><b>${r.ovr}</b></div></div>
  <div class="rv-arch"><span class="rv-tag">${esc(r.archetype.toUpperCase())}</span>${r.attrs.map(a=>`<div>${stars(a.stars)}<span>${a.name.toUpperCase()}</span></div>`).join('')}</div>
  <div class="rv-info">${[['POSITION',b.position.toUpperCase()+(b.assigned?'*':'')],['HEIGHT',b.height+(b.assigned?'*':'')],['ENERGY',energyWord(p.energy).toUpperCase()],['MORALE',moraleWord(p.morale).toUpperCase()],['CLASS',esc(p.year).toUpperCase()],['STATUS',p.injury?'INJURED':p.gpa<2?'INELIGIBLE':p.starter?'STARTER':p.minutes?'ROTATION':'BENCH']].map(([a,v])=>`<div><span class="rv-tag">${a}</span><strong>${v}</strong></div>`).join('')}</div></div>
  <div class="rv-stats">${[['PPG',line.ppg],['RPG',line.rpg],['APG',line.apg],['SPG',line.spg],['BPG',line.bpg],['FG%',line.fgp]].map(([a,v])=>`<div><strong>${v==null?'0.0':v.toFixed(1)}</strong><span>${a}</span></div>`).join('')}<small>${line.est?`2025–26 estimate from the team's real scoring · no games played yet`:`Your season · ${line.gp} game${line.gp===1?'':'s'}`}</small></div></div>
 <div class="rv-side">${btn('Full profile','player','secondary small',`data-id="${p.id}"`)}<label class="rv-start"><input type="checkbox" data-starter="${p.id}" ${p.starter?'checked':''} ${state.match?'disabled':''}> Starter</label></div>
 <button class="rv-arrow next" data-action="rv-cycle" data-step="1" aria-label="Next player"><svg viewBox="0 0 24 24"><path d="M9 5l7 7-7 7"/></svg></button></section>`;}
function roster(){const sum=state.players.reduce((s,p)=>s+p.minutes,0);if(!state.players.some(p=>p.id===rosterSel))rosterSel=(state.players.find(p=>p.starter)||state.players[0])?.id;const sel=state.players.find(p=>p.id===rosterSel);const est=E.estimateLines(state);const assigned=state.players.some(p=>E.bio(p).assigned);
 const cell=v=>`<td class="grade g-${E.grade(v)[0]}">${E.grade(v)}</td>`;
 return `${header('THE PEOPLE BEHIND THE JERSEY','Roster & rotation','Set five starters and 160 minutes. Cycle through players with the arrows or ← →.')}<div class="toolbar"><span>${pill(`${state.players.length} / 15 roster spots`)} ${pill(`${sum} / 160 minutes`,sum===160?'good':'warn')}</span>${btn('Build eligible rotation','auto-lineup','primary')}</div>${sel?rosterCard(sel):''}
 <div class="table-wrap rv-table"><div class="rv-team"><span>${esc(team().label.toUpperCase())} · LAKE WASHINGTON KANGS</span><span>W–L ${state.wins}–${state.losses} · TEAM CHEMISTRY ${Math.round(state.chemistry)}%</span></div><table><thead><tr><th>Start</th><th>Name</th><th>POS</th><th>YR</th><th class="ovr-col">OVR</th><th title="Inside scoring">INS</th><th title="Mid-range">MID</th><th title="Three-point">3PT</th><th title="Perimeter defense">PER D</th><th title="Interior defense">INS D</th><th>Energy</th><th>Min</th><th title="Games played">GP</th><th title="Points per game">PPG</th><th title="Rebounds per game">RPG</th><th title="Assists per game">APG</th><th title="Steals per game">SPG</th><th title="Blocks per game">BPG</th></tr></thead><tbody>${state.players.map(p=>{const r=E.ratings(p),b=E.bio(p),g=p.games?E.perGame(p):est[p.id];return `<tr class="${p.id===rosterSel?'selected':''} ${E.eligible(p)?'':'out'}" data-select="${p.id}"><td><input type="checkbox" data-starter="${p.id}" ${p.starter?'checked':''} aria-label="Start ${esc(p.name)}" ${state.match?'disabled':''}></td><td><button class="player-cell" data-action="rv-select" data-id="${p.id}">${avatar(p,34)}<div><strong>${esc(p.name)}</strong><small>#${esc(p.number)}${E.eligible(p)?'':` · <span class="warn-text">${p.injury?'Injured':p.gpa<2?'Ineligible':'Exhausted'}</span>`}</small></div></button></td><td>${esc(b.position[0])}${b.assigned?'*':''}</td><td>${esc((p.year||'').slice(0,2).toUpperCase())}</td><td class="ovr-col"><b>${r.ovr}</b></td>${cell(r.ins)}${cell(r.mid)}${cell(r.tpt)}${cell(r.perd)}${cell(r.insd)}<td><span class="bar"><i style="width:${p.energy}%"></i></span>${Math.round(p.energy)}</td><td><input class="minutes" type="number" min="0" max="32" step="1" value="${p.minutes}" data-minutes="${p.id}" aria-label="Minutes for ${esc(p.name)}" ${state.match?'disabled':''}></td><td>${g.gp}</td><td class="${g.est?'est':''}"><b>${g.ppg.toFixed(1)}</b></td><td class="${g.est?'est':''}">${g.rpg.toFixed(1)}</td><td class="${g.est?'est':''}">${g.apg.toFixed(1)}</td><td class="${g.est?'est':''}">${g.spg.toFixed(1)}</td><td class="${g.est?'est':''}">${g.bpg.toFixed(1)}</td></tr>`}).join('')}</tbody></table></div>
 <p class="footnote"><span class="est-key">Italic</span> stats are 2025–26 estimates built from the team's real points per game; they switch to your simulated stats once a player appears in a game.${assigned?' * Position or height not published, so the game estimates it.':''}</p>`;}
function practice(){return `${header('DEVELOP THE WHOLE ATHLETE','Practice planner','Three preparation slots before every game. Trade short-term readiness against long-term development.')}<div class="toolbar"><label>Training group <select id="training-target"><option value="all">Whole team</option>${state.players.map(p=>`<option value="${p.id}" ${String(selected)===String(p.id)?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${pill(`${state.actions} / 3 slots available`)}</div><div class="cards three">${Object.entries(E.plans).map(([key,p],i)=>`<section class="card plan"><div class="plan-icon">${svg(PLAN_ICONS[i])}</div><span class="eyebrow">${p.cost} PROGRAM TOKENS · 1 SLOT</span><h2>${esc(p.name)}</h2><p>${['Repetition turns open looks into points. Builds skill but costs energy.','Move together. Sharpen fundamentals and build team chemistry.','Help a simulated injury recover and restore energy for game day.','Protect eligibility. Academic preparation is part of a healthy program.','A shared meal builds trust, morale and connection.'][i]}</p><details class="training-details"><summary>Training effects</summary><div class="effect-list"><span>Skill +${p.skill}</span><span>Energy ${p.energy>=0?'+':''}${p.energy}</span><span>Morale +${p.morale}</span><span>GPA ${p.gpa>=0?'+':''}${p.gpa.toFixed(2)}</span></div></details>${btn('Schedule session →','train','secondary wide',`data-plan="${key}" ${state.actions<1||state.finished||state.match?'disabled':''}`)}</section>`).join('')}<section class="card purple"><span class="eyebrow">PLAN WITH INTENTION</span><h2>What happens next?</h2><p>Fatigued players make fewer shots. A connected team creates better looks. Study hall keeps your lineup eligible.</p><p>Every session is recorded in your decision trail and postgame breakdown.</p></section></div>`;}
function recruit(){return `${header('FIND THE NEXT DIFFERENCE MAKER','Open tryouts','Fictional candidates join your real-roster simulation. Recruiting uses program tokens, never real money.')}<div class="toolbar">${pill(`${state.players.length} / 15 roster spots`)}<span>${state.tokens} tokens available</span></div><div class="cards three">${state.pool.map(p=>`<section class="card recruit"><div class="prospect-jersey">${p.number}</div><span class="eyebrow">FICTIONAL TRYOUT · ${esc(p.position.toUpperCase())}</span><h2>${esc(p.name)}</h2><div class="effect-list"><span>Skill <b>${p.skill}</b></span><span>Energy <b>${p.energy}</b></span><span>Sim. GPA <b>${p.gpa}</b></span></div>${btn(`Sign · ${p.cost} tokens`,'recruit','primary wide',`data-id="${p.id}" ${state.players.length>=15||state.tokens<p.cost||state.finished||state.match?'disabled':''}`)}</section>`).join('')||'<section class="card">All tryout candidates have been signed.</section>'}</div>`;}
function office(){return `${header('LEAD THE PROGRAM','Coach’s office','Your staff and conversations shape the team beyond the scoreboard.')}<div class="cards two"><section class="card"><span class="eyebrow">WEEKLY TEAM CHECK-IN</span><h2>Make time for your people.</h2><p>The bench wants a voice. The team needs resources. Schoolwork is piling up. Choose where you spend one preparation slot.</p>${[['listen','Listen to the bench','+7 morale · +5 chemistry'],['fundraise','Host a community clinic','+180 tokens · +40 fans · −5 energy'],['academics','Academic check-in','+0.18 simulated GPA']].map(([key,title,sub])=>`<button class="choice" data-action="talk" data-choice="${key}" ${state.conversation||state.actions<1||state.finished||state.match?'disabled':''}><strong>${title}</strong><span>${sub}</span><b>→</b></button>`).join('')}</section><section class="card"><span class="eyebrow">ONE ASSISTANT SLOT</span><h2>${state.assistant?esc(E.staff.find(x=>x.key===state.assistant).name):'Build your coaching staff.'}</h2><p>Assistant roles are fictional game choices. Their bonuses apply to your preparation sessions.</p>${E.staff.map(a=>`<div class="staff-row"><div><strong>${a.name}</strong><small>${a.detail}</small></div>${btn(state.assistant===a.key?'Hired':`${a.cost} tokens`,'hire','small',`data-key="${a.key}" ${state.assistant||state.finished||state.match?'disabled':''}`)}</div>`).join('')}${state.assistant?btn('Dismiss assistant','dismiss','text-button'):''}</section></div>${stage('short-arena')}`;}
function speedControls(){return `<div class="playback-controls"><span>VIEWING SPEED</span><div role="group" aria-label="Viewing speed">${[1,2,4].map(n=>btn(`${n}×`,'speed',playbackSpeed===n?'selected':'',`data-speed="${n}" aria-pressed="${playbackSpeed===n}"`)).join('')}</div></div>`;}
function teamStats(stats,opp='OPP'){if(!stats)return '';return `<div class="table-wrap team-compare"><table><thead><tr><th scope="col">Team stats</th><th scope="col">KANGS</th><th scope="col">${esc(String(opp).toUpperCase())}</th></tr></thead><tbody>${[['rebounds','Rebounds'],['assists','Assists'],['steals','Steals'],['blocks','Blocks']].map(([k,l])=>`<tr><td>${l}</td><td><b>${stats.home[k]}</b></td><td>${stats.away[k]}</td></tr>`).join('')}</tbody></table></div>`;}
function replayView(){const p=arena.presentation(),e=replayEvent;return `${header('THE FILM ROOM','Watch the play develop.','Recorded actions and outcomes. Replaying never changes your season.')}<div class="replay-layout">${stage('game-arena')}<div class="score-strip"><div>KANGS<strong id="live-home">${p?.home??e.home}</strong></div><div class="clock"><span>RECORDED PLAY</span><strong>#${e.number}</strong></div><div>VISITORS<strong id="live-away">${p?.away??e.visitor}</strong></div></div><p class="play-call" aria-live="polite"></p><div class="play-feed"></div>${speedControls()}${btn('Replay again','replay-again','primary')}${btn(arena.paused?'Resume replay':'Pause replay','replay-pause','secondary')}${btn('Back to season journal','journal','secondary')}</div>`;}
function scoreBug(m,o){const q=m.possession>64?'OT':`Q${Math.max(1,Math.min(4,Math.ceil(m.possession/16)))}`,clock=`${Math.max(0,8-Math.floor((m.possession?((m.possession-1)%16)+1:0)/2))}:00`,P=state?plan():null,tag=P&&state.week>=P.cut?P.runName.toUpperCase():`${esc(team().label.toUpperCase())} · ${esc((o.type||'REGULAR SEASON').toUpperCase())}`,to=Math.max(0,m.timeouts??0);
 return `<div class="score-strip bug2k" role="group" aria-label="Scoreboard"><span class="bug-tag">${tag}</span><div class="bug-team home"><img src="${LOGO}" alt=""><div class="bug-name"><b>KANGS</b><small>${state.wins}–${state.losses} · <span class="bug-to" aria-label="${to} timeouts left">${[0,1,2].map(i=>`<i class="${i<to?'on':''}"></i>`).join('')}</span></small></div><strong id="live-home">${arena.presentation()?.home??m.home}</strong></div><div class="bug-mid"><span>${q}</span><strong>${clock}</strong><small>POSS ${m.possession}</small></div><div class="bug-team away"><strong id="live-away">${arena.presentation()?.away??m.away}</strong><div class="bug-name"><b>${esc(crestText(o.opponent))}</b><small>${esc(o.opponent)}</small></div><span class="bug-crest">${esc(crestText(o.opponent)).slice(0,3)}</span></div><span class="bug-slogan">ALWAYS RISING</span></div>`;}
function game(){if(replayEvent)return replayView();if(state.finished&&!closingMatch)return endscreen();const o=closingMatch?state.results.at(-1):E.opponent(state),m=state.match||closingMatch;return `${header(m?'LIVE FROM THE FIELDHOUSE':'PREPARE. ADAPT. EXECUTE.',m?'Game day. Your call.':`Kangs vs ${esc(o.opponent)}`,`${esc(o.date)} · ${esc(o.venue)} · ${state.week>=plan().cut?`${plan().runName} · simulated elimination game`:`${esc(o.type??'Published')} matchup · simulated outcome`}`)}<div class="game-layout"><div class="court-panel">${stage('game-arena')}${m?`${scoreBug(m,o)}<p class="play-call" aria-live="polite">${esc(arena.presentation()?.clip?.label||'Choose a play and watch the possession develop.')}</p><details class="commentary-drawer"><summary>Play-by-play</summary><div class="play-feed">${(arena.isPlaying()?m.feed.slice(2):m.feed).map((t,i)=>`<p class="${i===0?'new':''}">${esc(t)}</p>`).join('')||'<p>The crowd is ready. Call the opening possession.</p>'}</div></details>`:`<section class="card"><span class="eyebrow">SCOUTING REPORT</span><h2>${esc(o.opponent)}</h2><p>Reference result: Lake Washington ${o.points}–${o.against}. Your result has not been written.</p><div class="effect-list"><span>Game opponent strength <b>${o.rating}</b></span><span>Style <b>${state.scouted?o.style:'Unscouted'}</b></span></div>${state.scouted?`<p class="notice">${{perimeter:'Close out on shooters. Zone is the recommended defensive response.',paint:'Protect the interior. Pressure can disrupt their entry passes.',transition:'Control the rhythm. Balanced defense keeps your team organized.'}[o.style]} This scout profile is part of the simulation.</p>`:btn('Watch opponent film · 50 tokens / 1 slot','scout','secondary')}</section>`}${m?`<details class="box-drawer"><summary>Box score</summary>${teamStats(m.stats,o.opponent)}${boxTable(m.line,'KANGS',true)}</details>`:''}</div><aside class="right-rail"><section class="card"><span class="eyebrow">${m?'THE SIDELINE':'YOUR STARTING FIVE'}</span>${m?`<h2>Call the play</h2><label>SYSTEM<select id="tactic">${[['balanced','Balanced'],['zone','Zone / closeouts'],['pressure','Pressure defense'],['perimeter','Spread / shoot threes']].map(([v,n])=>`<option value="${v}" ${m.tactic===v?'selected':''}>${n}</option>`).join('')}</select></label><label>TEMPO<select id="pace"><option value="steady" ${m.pace==='steady'?'selected':''}>Steady</option><option value="fast" ${m.pace==='fast'?'selected':''}>Fast break</option></select></label>${speedControls()}${btn((closingMatch?(arena.paused?'Resume final play':'Pause final play'):auto?'Pause game':arena.paused?'Resume game':'▶ Watch live')+kbd('W'),'auto','primary wide')}${btn('Next play →'+kbd('SPACE'),'step','secondary wide',arena.isPlaying()||closingMatch?'disabled':'')}${btn(`Timeout huddle · ${m.timeouts} left${kbd('T')}`,'timeout','secondary wide',m.timeouts&&!closingMatch?'':'disabled')}`:`<h2>Ready for tip-off?</h2>${state.players.filter(p=>p.starter).map(p=>`<div class="lineup-row"><span class="jersey">${p.number}</span><strong>${esc(p.name)}</strong><span>${p.minutes}m</span></div>`).join('')}<p>${state.players.reduce((s,p)=>s+p.minutes,0)} / 160 minutes assigned</p>${btn('Adjust rotation','rotation','secondary wide')}${btn('Tip off →','start-match','primary wide')}`}</section></aside></div>`;}
function locker(){return `${header('WEAR YOUR IDENTITY','Locker room','Choose the kit your players wear in the 3D gym. Rename players through their roster profiles.')}<div class="locker-layout">${stage('locker-arena')}<section class="card"><span class="eyebrow">KANGS TEAM ISSUE</span><h2>Make it yours.</h2><div class="kit-options">${[['home','Home purple'],['away','Away white'],['alternate','Midnight alternate']].map(([k,t])=>`<button data-action="kit" data-kit="${k}" class="kit ${state.kit===k?'selected':''}"><div class="shirt ${k}">K<br><b>11</b></div><strong>${t}</strong></button>`).join('')}</div><label>Jersey number color<input type="color" id="trim" value="${state.trim}"></label><p>Original jersey designs inspired by the school’s purple and white identity. No official logo or athlete likeness is used.</p></section></div>`;}
function journal(){const teams={};for(const r of state.results){teams[r.opponent]??={name:r.opponent,w:0,l:0};r.won?teams[r.opponent].l++:teams[r.opponent].w++;}const ranks=Object.values(state.standings||{'Lake Washington':{name:'Lake Washington',w:state.wins,l:state.losses},...teams}).sort((a,b)=>b.w/Math.max(1,b.w+b.l)-a.w/Math.max(1,a.w+a.l));return `${header('THE STORY OF YOUR SEASON','Season journal','Your simulated record, decisions, standings and defining moments.')}<div class="season-path">${(P=>`<span class="${state.week<P.stretch?'current':''}">01 / Regular season</span><i>→</i><span class="${state.week>=P.stretch&&state.week<P.cut?'current':''}">02 / ${P.stretchName}</span><i>→</i><span class="${state.week>=P.cut?'current':''}">03 / ${P.runName}</span>`)(plan())}</div>${state.finished?`<section class="card purple"><span class="eyebrow">${state.champion?'THE BANNER IS YOURS':'EVERY SEASON TEACHES YOU SOMETHING'}</span><h2>${state.champion?'State champions.':'The final whistle.'}</h2><p>Coach ${esc(state.coach)} finished ${state.wins}–${state.losses}, grew a fanbase of ${state.fans}, and developed a team with ${Math.round(state.chemistry)} chemistry.</p>${btn('Start a new season','new-season','secondary')}${btn('Export this season','export','secondary')}</section>`:''}<div class="cards two"><section class="card"><span class="eyebrow">YOUR RESULTS</span><h2>The scoreboard tells one part.</h2>${state.results.map((r,i)=>`<button class="result-row" data-action="result" data-index="${i}"><b class="${r.won?'win':'loss'}">${r.won?'W':'L'}</b><span>${esc(r.opponent)}<small>${esc(r.date)}</small></span><strong>${r.home}–${r.away}</strong><span>Replay ↗</span></button>`).join('')||'<p>Play your opening game to start your story.</p>'}</section><section class="card"><span class="eyebrow">PROGRAM STANDINGS</span><h2>The campaign table</h2><p>Fictional campaign standings: other opponents play simulated background fixtures each round. These are not official KingCo standings.</p>${ranks.map((t,i)=>`<div class="staff-row"><span>${i+1}. ${esc(t.name)}</span><b>${t.w}–${t.l}</b></div>`).join('')}<h3>Decision trail</h3><div class="journal-log">${state.log.map(l=>`<p><small>GAME ${l.week}</small>${esc(l.text)}</p>`).join('')||'<p>Your decisions will appear here.</p>'}</div></section></div>`;}
function endscreen(){return `${header('THE FINAL WHISTLE',state.champion?'You brought it home.':'Your season is complete.')} ${stage()}<section class="card ending"><h2>${state.champion?'A banner earned. A program built.':'A different ending starts with a different decision.'}</h2><p>Final record: ${state.wins}–${state.losses}. ${state.champion?'The Kangs are champions in your alternate season.':'The state run has ended. Review your decision trail and build your next strategy.'}</p>${btn('Watch your season story','journal','primary')}${btn('Start a new season','new-season','secondary')}</section>`;}
function dataView(){const levels=Object.entries(data.levels);const rec=t=>`${t.games.filter(g=>g.points>g.against).length}–${t.games.filter(g=>g.points<g.against).length}`;return `${header('REAL PROGRAM. TRANSPARENT SOURCES.','The real Kangs',`Published ${esc(data.season)} Varsity, Junior Varsity and C-Team rosters and results, kept separate from your simulation.`)}<section class="card source-summary"><div>${pill('DATED PUBLIC SNAPSHOT','good')}<h2>Lake Washington · Kirkland, WA</h2><p>Last successful source check: ${new Date(data.checkedAt).toLocaleString()}. The scheduled updater checks KingCo daily; this completed season is not a live score feed.</p><p>${levels.map(([,t])=>`${esc(t.label)} ${rec(t)}`).join(' · ')}</p></div>${btn('Check for updated snapshot','refresh','secondary')}</section><p class="notice">Each difficulty coaches one real team: C Team (Rookie) → C-Team, Junior Varsity (All-Star) → JV, Varsity (Hall of Fame) → Varsity. KingCo publishes rosters and final scores, not individual statistics, so player stats appear only in your simulation. Refreshing sources never changes a saved season.</p>${levels.map(([key,t])=>`<h2 class="section-title">${esc(t.label)} · ${rec(t)}</h2><div class="table-wrap"><table><thead><tr><th>#</th><th>Player</th><th>Position</th><th>Height</th><th>Grade</th></tr></thead><tbody>${t.players.map(p=>`<tr><td>${p.number}${p.numberAssigned?'<span class="muted" title="Jersey number assigned by the game; not published">*</span>':''}</td><td>${esc(p.name)}</td><td>${esc(p.position)}</td><td>${esc(p.height)}</td><td>${esc(p.year)}</td></tr>`).join('')}</tbody></table></div>${t.players.some(p=>p.numberAssigned)?'<p class="footnote">* Not published; assigned by the game for jerseys.</p>':''}<details class="schedule-drawer"><summary>${esc(t.label)} schedule &amp; actual results (${t.games.length} games)</summary><div class="table-wrap"><table><thead><tr><th>Date</th><th>Opponent</th><th>Type</th><th>Actual LW score</th><th>Venue</th></tr></thead><tbody>${t.games.map(g=>`<tr><td>${g.date}</td><td>${g.home?'vs':'at'} ${esc(g.opponent)}</td><td>${esc(g.type)}</td><td class="${g.points>g.against?'good-text':'warn-text'}">${g.points>g.against?'W':'L'} ${g.points}–${g.against}</td><td>${esc(g.venue)}</td></tr>`).join('')}</tbody></table></div></details>${(o=>`<details class="schedule-drawer"><summary>${esc(t.label)} opponent rosters (${o.filter(([,v])=>v.real).length} real, ${o.filter(([,v])=>!v.real).length} fictional)</summary>${o.map(([n,v])=>`<p class="opp-roster"><b>${esc(n)}</b> <span class="muted">${v.real?'KingCo roster':'fictional names; no roster published'}</span><br>${v.players.map(x=>`#${x.number} ${esc(x.name)}`).join(' · ')}</p>`).join('')}</details>`)(Object.entries(t.opponents||{}))}<p class="footnote"><a href="${esc(t.source)}" target="_blank" rel="noreferrer">Open the ${esc(t.label)} page on KingCo Athletics</a></p>`).join('')}`;}
function render(){document.body.dataset.view=view;document.body.classList.toggle('live-match',view==='game'&&!!(state?.match||closingMatch||replayEvent));document.body.append(host);if(view==='landing'){app.innerHTML=landing();}else{const route=routes.find(r=>r[0]===view);app.innerHTML=`<div class="shell"><aside class="sidebar"><a href="#" class="brand" data-action="home"><img class="brand-logo" src="${LOGO}" alt="" width="58" height="43"><div>KANGS<span>BASKETBALL OPERATIONS</span></div></a><div class="season-badge">${esc((data?.season??'2025–26').replace('–','—'))}<span>THE CHAMPIONSHIP PROJECT</span></div><nav aria-label="Program navigation">${routes.map(([v,n,t])=>`<button data-view="${v}" class="nav-item ${view===v?'active':''}" ${view===v?'aria-current="page"':''}><span class="nav-icon">${svg(NAV_ICONS[v])}</span><b class="nav-label">${t}</b><em class="nav-num">${n}</em></button>`).join('')}</nav><div class="sidebar-bottom">${btn('Rulebook & controls','rules')}${btn('Credits & sources','credits')}<div class="coach-badge"><span>${esc(state.coach[0].toUpperCase())}</span><div>Coach ${esc(state.coach)}<small>${(d=>d?`${d.short} · ${d.tier}`:state.difficulty.toUpperCase())(E.DIFFICULTIES[state.difficulty])}</small></div></div></div></aside><div class="workspace"><header class="topbar"><span>ROAD TO THE CHAMPIONSHIP <b>/ ${route?.[2]||'Program'}</b></span><div>${btn(sound?'Sound on':'Sound off','sound')}${btn(arena.motion?'Motion on':'Motion off','motion')}${btn('Save / export','export')}${btn('Help','rules')}${btn('Title','title')}</div></header><main class="content">${({home,roster,practice,recruit,staff:office,game,locker,season:journal,data:dataView}[view]||home)()}</main><footer>ALWAYS RISING.<span>Auto-saved locally · Fictional simulation / sourced public roster</span></footer></div></div>`;}
 const target=$('#arena');if(target){arena.mount(target);arena.update(state);}else host.hidden=true;host.hidden=!target;
 if(tutorial>0)renderTutorial();if(arena.event)syncPresentation(arena.presentation());
}
function renderTutorial(){const steps=[['Welcome to your program.','Start by choosing your five starters and assigning 160 minutes.','roster'],['Build the whole athlete.','Use three preparation slots for skills, recovery, study or team bonding.','practice'],['Your decisions follow you.','Hire one assistant and talk with your team. Morale and chemistry change performance.','staff'],['Make the game yours.','Scout the opponent, tip off and change tactics live. Win the state bracket in this one season.','game']];const [title,body]=steps[tutorial-1];const el=document.createElement('div');el.className='tutorial';el.innerHTML=`<div class="tutorial-arrow">↖</div><span class="eyebrow">FIRST-TIME COACH · ${tutorial}/4</span><h3>${title}</h3><p>${body}</p>${btn(tutorial===4?'Let’s coach':'Next →','tutorial-next','primary')}${btn('Skip tour','tutorial-skip','text-button')}`;app.append(el);}
function credits(){show(`<span class="eyebrow">BUILT FOR THE LOVE OF THE GAME</span><h1>Credits & sources</h1><h2>Creators</h2><p class="creator-names">Ajisth Sareen<br>Raghav Krishnan<br>Malhar Pawar</p><h2>Assets, software & research</h2><ul class="sources"><li><a href="https://kenney.nl/assets/furniture-kit" target="_blank" rel="noreferrer">Kenney Furniture Kit</a> — CC0. Imported GLB bench, chair, table, cabinet and plant. The pack also includes Unity-compatible FBX files. Models loaded in this scene: ${arena.models}/5.</li><li><a href="https://threejs.org/" target="_blank" rel="noreferrer">Three.js</a> — MIT. WebGL rendering, OrbitControls and GLTFLoader.</li><li><a href="https://fonts.google.com/specimen/Barlow" target="_blank" rel="noreferrer">Barlow</a> and <a href="https://fonts.google.com/specimen/Barlow+Condensed" target="_blank" rel="noreferrer">Barlow Condensed</a> (Jeremy Tribby) — SIL Open Font License, bundled locally.</li><li><a href="https://vite.dev/" target="_blank" rel="noreferrer">Vite</a> — MIT. Build tooling.</li><li><a href="${data.source}" target="_blank" rel="noreferrer">KingCo Athletics</a> (WPA Network team widgets) — public ${esc(data.season)} Varsity, JV and C-Team rosters, schedules and final scores. See Real Kangs Data.</li><li><a href="https://www.kangsbasketball.com/hs" target="_blank" rel="noreferrer">Lake Washington Boys Basketball</a> — school program identity and context.</li><li><a href="https://www.nfhs.org/sports/basketball/rules" target="_blank" rel="noreferrer">NFHS basketball rules</a> — introductory rulebook reference; detailed officiating is abstracted in the game.</li><li><a href="https://www.fbla.org/competitive-events/computer-game-simulation-programming/" target="_blank" rel="noreferrer">FBLA event</a> and <a href="https://greektrack-fbla-public.s3.us-east-1.amazonaws.com/files/1/High%20School%20Competitive%20Events%20Resources/Individual%20Guidelines/Presentation%20Events/Computer-Game-Simulation-Programming.pdf" target="_blank" rel="noreferrer">2026–27 guidelines and rubric</a> — Road to the Championship topic.</li></ul><p>Court, basketball, stylized characters, jerseys, interface and synthesized sounds are generated in code. Characters are not likenesses of real students. Developed with AI coding assistance (OpenAI Codex). No official school endorsement.</p><p>Three.js renders the 3D game; accessible HTML overlays handle forms and coaching controls. Unity prefab files are not run in the browser: licensed cross-engine models are imported as GLB.</p>`);}
const RULE_TABS=['Controls','Goal','Difficulty','Rotation','Prep & tokens','Game day','Court rules','Data & saves'];
function rules(tab=0){tab=(tab+RULE_TABS.length)%RULE_TABS.length;const P=state?plan():null;const row=(keys,text)=>`<div class="ctl-row"><div class="ctl-keys">${keys}</div><span>${text}</span></div>`;const chips=list=>`<div class="rule-chips">${list.map(([a,b])=>`<div><strong>${a}</strong><span>${b}</span></div>`).join('')}</div>`;
 const body=[
 ()=>`<p class="rule-lead">Click any button, or use the keys below.</p><div class="ctl-grid">${row(micon('drag'),'Drag the gym to orbit')}${row(micon('scroll'),'Scroll to zoom')}${row(kbd('SPACE'),'Next play')}${row(kbd('W'),'Watch live / pause')}${row(kbd('T'),'Timeout huddle')}${row(kbd('1')+kbd('2')+kbd('3')+kbd('4'),'Wide · Courtside · Follow · Player view')}${row(kbd('H'),'Open this handbook')}${row(kbd('ESC'),'Close a window')}${row(kbd('TAB')+kbd('ENTER'),'Move and select without a mouse')}${row(micon('tap'),'On phones, tap buttons and drag the gym')}</div>`,
 ()=>`<p class="rule-lead">Coach your real Lake Washington team through its real schedule.</p>${chips(P?[[`${P.need} of ${P.cut}`,'early wins to qualify'],['4 games',`${P.runName}, win or go home`],[String(P.n),'games this season']]:[['Qualify','win enough early games'],['4 games','final run, win or go home'],['1','championship']])}<p>Lose in the final run and the season ends. Win all four and you're champions.</p>`,
 ()=>`<p class="rule-lead">Your difficulty decides which real Kangs team you coach.</p><div class="rule-chips">${Object.values(E.DIFFICULTIES).map(d=>{const t=data.levels?.[d.level];return `<div><strong>${d.label}</strong><span>${esc(d.blurb)} · ${t?.games.length||0} real games</span></div>`}).join('')}</div><p>Higher levels face stronger opponents with smaller margins.</p>`,
 ()=>`<p class="rule-lead">Set your rotation before every tip-off.</p>${chips([['5','starters'],['160','total minutes'],['32','max per player'],['15+','energy to play'],['2.0+','GPA to be eligible'],['0','active injuries']])}<p>Short on time? <b>Build eligible rotation</b> on the Roster page fills a legal lineup for you.</p>`,
 ()=>`<p class="rule-lead">Spend prep slots and tokens before each game.</p>${chips([['3','prep slots per game'],['+160','tokens per game'],['+70','bonus for a win'],['15','roster cap'],['1','assistant coach']])}<p>Practice builds skill but costs energy. Recovery and study keep players available. Released players give no refund.</p>`,
 ()=>`<p class="rule-lead">Call each possession or let it play live.</p>${chips([['3','timeouts'],['OT','if tied'],['1× 2× 4×','viewing speed']])}<p>Change system and tempo any time. Low energy means worse shots and more injury risk. Viewing speed never changes the result.</p>`,
 ()=>`<p class="rule-lead">Two points inside the arc, three outside it.</p><ul class="rule-list"><li><b>Travel</b> Keep a legal dribble and pivot.</li><li><b>Out of bounds</b> Last touch loses possession.</li><li><b>Fouls</b> Illegal contact means a throw-in or free throws.</li><li><b>Goaltending</b> Don't touch a shot on its way down.</li><li><b>Conduct</b> Respect officials, opponents and teammates.</li></ul><p class="muted">Simplified guide. Full rules: <a href="https://www.nfhs.org/sports/basketball/rules" target="_blank" rel="noreferrer">NFHS basketball</a>. The 2.0 GPA line is a game rule, not school policy.</p>`,
 ()=>`<p class="rule-lead">Real rosters and results. Your season is a simulation.</p>${chips([[String(Object.values(data.levels||{}).reduce((a,t)=>a+t.players.length,0)),'real KingCo players'],[String(Object.values(data.levels||{}).reduce((a,t)=>a+t.games.length,0)),'real matchups'],['Auto','save after every move']])}<p>Skills, GPA, health and in-game stats are simulated. Use Save / export for a file backup, and Import season on the title screen to load it.</p>`][tab];
 show(`<span class="eyebrow">THE COACH’S HANDBOOK</span><h1>How to play</h1><div class="rule-tabs" role="tablist" aria-label="Handbook sections">${RULE_TABS.map((t,i)=>`<button role="tab" aria-selected="${i===tab}" class="${i===tab?'active':''}" data-action="rules" data-tab="${i}">${t}</button>`).join('')}</div><section class="rule-panel" role="tabpanel" data-rules-tab="${tab}"><h2>${RULE_TABS[tab]}</h2>${body()}</section><div class="rule-nav">${btn('← Prev','rules','secondary small',`data-tab="${tab-1}" ${tab===0?'disabled':''}`)}<div class="rule-dots" aria-hidden="true">${RULE_TABS.map((t,i)=>`<i class="${i===tab?'on':''}"></i>`).join('')}</div>${btn(tab===RULE_TABS.length-1?'Done':'Next →',tab===RULE_TABS.length-1?'close':'rules','primary small',`data-tab="${tab+1}"`)}</div>`);
 modal.querySelector('.rule-tabs .active')?.focus({preventScroll:true});}
function profile(id){const p=state.players.find(p=>p.id===+id);if(!p)return;const b=E.bio(p),r=E.ratings(p);show(`<div class="profile-head">${avatar(p,96)}<div><span class="eyebrow">PLAYER PROFILE · #${p.number}</span><h1>${esc(p.name)}</h1><p>${esc(b.position)} · ${esc(b.height)}${b.assigned?' (est.)':''} · ${esc(p.year)} · ${r.ovr} OVR · ${esc(r.archetype)}</p></div></div><div class="profile-stats">${[['Skill',Math.round(p.skill)],['Energy',Math.round(p.energy)],['Morale',Math.round(p.morale)],['Sim. GPA',p.gpa.toFixed(2)],...(g=>[[g.est?'PPG (est.)':'PPG',f1(g.ppg)],['RPG',f1(g.rpg)],['APG',f1(g.apg)],['SPG',f1(g.spg)],['BPG',f1(g.bpg)],['FG%',f1(g.fgp)]])(E.statLine(state,p)),['Injury risk',p.energy<45?'Elevated':'Low']].map(([a,b])=>`<div><strong>${b}</strong><span>${a}</span></div>`).join('')}</div><p>${p.injury?`Simulated injury: ${p.injury} recovery steps remaining.`:'Available health status is fictional; no private athlete information is used.'}</p><form id="rename-form" data-id="${p.id}"><label for="rename">Player display name</label><input id="rename" name="name" maxlength="36" value="${esc(p.name)}" required><button class="primary" ${state.match?'disabled':''}>Save name</button></form><small>${p.custom?'Creator addition, not on the published roster.':`Original source name: ${esc(p.originalName)}.`} Renaming only changes your simulation.</small><div class="modal-actions">${btn('Release from roster','release','danger-button',`data-id="${p.id}" ${state.match?'disabled':''}`)}</div>`);}
function result(index){const r=state.results[index];if(!r)return;show(`<span class="eyebrow">THE FILM ROOM · ${r.won?'WIN':'LOSS'}</span><h1>${r.home}–${r.away}</h1><h2>Kangs vs ${esc(r.opponent)}</h2><p>${esc(r.reason)}</p><h3>What you did before tip-off</h3>${r.ripples.map(x=>`<p class="notice">${esc(x.detail)}</p>`).join('')||'<p>No preparation sessions were recorded for this matchup.</p>'}<h3>Defining possessions</h3>${r.events.slice(-5).map((e,i)=>`<button class="choice" data-action="replay" data-index="${index}" data-event="${r.events.length-5+i}"><strong>${esc(e.player)} · ${e.points?`+${e.points}`:esc(e.plays?.[0]?.outcome||'miss')}</strong><span>${esc(e.explanation)}${e.shotChance?` Shot quality: ${e.shotChance}%.`:''}</span><b>▶</b></button>`).join('')}<details class="analysis-drawer"><summary>Why it happened · decision analysis</summary><p>Latest possession: changes to the base shot probability, in percentage points. These are model contributions, not claims about what would have happened in real life.</p><div class="effect-list">${Object.entries(r.events.at(-1)?.impacts||{}).map(([key,n])=>`<span>${esc(key)}: ${n>=0?'+':''}${n.toFixed(1)} pp</span>`).join('')}</div></details><h3>Box score</h3>${r.line?boxTable(r.line,`KANGS ${r.home} · ${r.opponent.toUpperCase()} ${r.away}`):Object.entries(r.box).filter(([,p])=>p>0).map(([id,points])=>`<div class="staff-row"><span>${esc(state.players.find(p=>p.id===+id)?.name||'Former roster player')}</span><b>${points} PTS</b></div>`).join('')}`);}
async function refresh(){try{const next=await fetch(`${import.meta.env.BASE_URL}data/kangs.json?t=${Date.now()}`,{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json();});if(!next.levels?.varsity?.players?.length)throw Error();data=next;render();notify(`KingCo snapshot from ${new Date(data.checkedAt).toLocaleString()} is loaded.`,{type:'success',title:'Real data checked'});}catch{notify('Keeping the last verified data.',{type:'error',title:'Snapshot unavailable'});}}
function syncPresentation(p){
 if(!p)return;
 if($('#live-home'))$('#live-home').textContent=p.home;if($('#live-away'))$('#live-away').textContent=p.away;
 const banner=$('.live-action');if(banner)banner.textContent=`${p.clip.team==='home'?'KANGS':'VISITORS'} · ${p.clip.label||'Recorded shot'}`;
 const call=$('.play-call');if(call)call.textContent=p.resolved?p.clip.commentary:`${p.clip.player} · ${p.phase} · ${p.clip.contest} look`;
 const feed=$('.play-feed');if(feed){const m=state.match||closingMatch;const rows=replayEvent?(p.index===1&&p.resolved?arena.clips.map(c=>c.commentary).reverse():p.index===0&&!p.resolved?[]:[arena.clips[0].commentary]):m?(p.index===1&&p.resolved?m.feed:p.index===0&&!p.resolved?m.feed.slice(2):m.feed.slice(1)):[];feed.innerHTML=rows.map((text,i)=>`<p class="${i===0?'new':''}">${esc(text)}</p>`).join('');}
 const next=$('[data-action="step"]');if(next)next.disabled=arena.isPlaying()||!!closingMatch;
 if(p.done&&pendingResult!==null){const index=pendingResult;pendingResult=null;closingMatch=null;auto=false;arena.clear();render();result(index);}
}
arena.onPresentation=p=>{if(p.resolved&&p.clip.points)tone();syncPresentation(p);};
function step(){
 if(!state.match||arena.isPlaying())return;
 closingMatch=state.match;const event=E.possession(state);arena.play(event);arena.speed=playbackSpeed;save();
 if(!state.match){pendingResult=state.results.length-1;auto=false;}else closingMatch=null;
 render();
}
function finishTour(){tutorial=0;try{localStorage.setItem(TUTORIAL,'seen');}catch{}render();}
function go(v){view=v;auto=false;arena.clear();closingMatch=null;pendingResult=null;replayEvent=null;render();if(v==='locker')arena.setView('court');else if(v==='staff')arena.setView('office');else arena.setView(v==='game'?'follow':'broadcast');}
app.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='start-form'){const f=new FormData(e.target);if(state&&!confirm('Replace this browser’s saved season? Export it first if you want to keep it.'))return;state=E.createGame(data,f.get('coach'),f.get('difficulty'));E.autoLineup(state);save();view='home';try{if(!localStorage.getItem(TUTORIAL)){tutorial=1;localStorage.setItem(TUTORIAL,'seen');}}catch{tutorial=1;}render();}});
modal.addEventListener('close',()=>{arena.paused=false;});
/* Live-game drawers share one corner of the court: opening one closes the other so they never overlap. */
document.addEventListener('toggle',e=>{const d=e.target;if(!d.open||!document.body.classList.contains('live-match')||!d.matches('.commentary-drawer,.box-drawer'))return;document.querySelectorAll('.commentary-drawer[open],.box-drawer[open]').forEach(o=>{if(o!==d)o.open=false;});},true);
modal.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='rename-form'){const name=new FormData(e.target).get('name').trim();if(!name)return;state.players.find(p=>p.id===+e.target.dataset.id).name=name.slice(0,36);save();modal.close();render();}});
document.addEventListener('change',e=>{const el=e.target;try{if(el.matches('[data-starter]')){if(state.match)throw Error('Finish the game first.');const p=state.players.find(p=>p.id===+el.dataset.starter);p.starter=el.checked;save();}if(el.matches('[data-minutes]')){if(state.match)throw Error('Finish the game first.');const n=Number(el.value);if(!Number.isInteger(n)||n<0||n>32)throw Error('Enter whole minutes between 0 and 32.');state.players.find(p=>p.id===+el.dataset.minutes).minutes=n;save();render();}if(el.id==='training-target')selected=el.value;if(el.id==='tactic'&&state.match){state.match.tactic=el.value;save();}if(el.id==='pace'&&state.match){state.match.pace=el.value;save();}if(el.id==='trim'){state.trim=el.value;save();arena.update(state);}}catch(err){notify(err.message,{type:'error'});render();}});
document.addEventListener('click',async e=>{const el=e.target.closest('button[data-action],a[data-action],button[data-view]');if(!el)return;e.preventDefault();if(el.dataset.view){go(el.dataset.view);return;}const a=el.dataset.action;const was=state?{tokens:state.tokens,actions:state.actions,chemistry:state.chemistry}:null;try{
 if(a==='close'){modal.close();arena.paused=false;return;}if(a==='credits'){credits();return;}if(a==='rules'){rules(+(el.dataset.tab||0));return;}if(a==='camera'){setCamera(el.dataset.camera);return;}if(a==='sound'){sound=!sound;tone();render();return;}if(a==='motion'){arena.motion=!arena.motion;document.body.classList.toggle('reduced',!arena.motion);render();return;}if(a==='title'){go('landing');return;}if(a==='continue'||a==='home'){go('home');return;}if(a==='game'){go('game');return;}if(a==='rotation'){go('roster');return;}if(a==='journal'){go('season');return;}if(a==='new-season'){go('landing');return;}if(a==='refresh'){await refresh();return;}
 if(a==='tutorial-skip'){finishTour();return;}if(a==='tutorial-next'){if(tutorial===4){finishTour();return;}tutorial++;view=['roster','practice','staff','game'][tutorial-1];render();return;}
 if(a==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='kangs-season.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Saved as kangs-season.json in your downloads.',{type:'success',title:'Season exported'});return;}
 if(a==='import'){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.hidden=true;document.body.append(input);input.oncancel=()=>input.remove();input.onchange=async()=>{try{if(input.files[0].size>2e6)throw Error('Save file too large');const s=JSON.parse(await input.files[0].text());if(!E.validSave(s))throw Error('This is not a compatible Kangs season file.');if(state&&!confirm('Replace the current local season with this save?'))return;state=s;save();go('home');}catch(err){notify(err.message,{type:'error',title:'Import failed'});}finally{input.remove();}};input.click();return;}
 if(a==='player'){profile(el.dataset.id);return;}if(a==='rv-select'){rosterSel=+el.dataset.id;render();return;}if(a==='rv-cycle'){cycleRoster(+el.dataset.step);return;}if(a==='result'){result(+el.dataset.index);return;}if(a==='replay'){const event=state.results[+el.dataset.index].events[+el.dataset.event];modal.close();go('game');replayEvent=event;arena.play(event);arena.speed=playbackSpeed;render();return;}if(a==='replay-pause'){arena.paused=!arena.paused;render();return;}if(a==='replay-again'){arena.play(replayEvent);arena.speed=playbackSpeed;render();return;}if(a==='speed'){playbackSpeed=Number(el.dataset.speed);arena.speed=playbackSpeed;render();return;}
 if(a==='train')E.train(state,el.dataset.plan,selected);
 if(a==='recruit')E.recruit(state,el.dataset.id);
 if(a==='release'){if(!confirm('Release this player from your simulation roster?'))return;E.release(state,el.dataset.id);modal.close();}
 if(a==='hire')E.hire(state,el.dataset.key);
 if(a==='dismiss'){if(state.match)throw Error('Finish the current game first.');state.assistant=null;E.log(state,'Assistant dismissed. No refund.');}
 if(a==='talk')E.talk(state,el.dataset.choice);
 if(a==='scout')E.scout(state);
 if(a==='auto-lineup')E.autoLineup(state);
 if(a==='kit')state.kit=el.dataset.kit;
 if(a==='start-match'){E.startMatch(state);auto=false;arena.clear();arena.setView('follow');}
 if(a==='auto'&&closingMatch){arena.paused=!arena.paused;render();return;}
 if(a==='auto'){auto=!auto;arena.paused=!auto;if(auto&&!arena.isPlaying()){step();return;}}
 if(a==='step'){auto=false;arena.paused=false;step();return;}
 if(a==='timeout'){auto=false;show(`<span class="eyebrow">TIMEOUT HUDDLE</span><h1>Bring it in.</h1><p>Three timeouts per game. Both approaches boost the next eight possessions.</p>${btn('Calm the team · +4 energy','huddle','primary wide','data-message="calm"')}${btn('Show belief · +3 morale','huddle','secondary wide','data-message="belief"')}`);return;}
 if(a==='huddle'){E.timeout(state,el.dataset.message);modal.close();arena.paused=false;}
 save();render();if(['train','recruit','hire','talk','scout','release','dismiss'].includes(a))actionToast(a,was);
 }catch(err){auto=false;notify(err.message,{type:'error'});lastError=err.message;}});
setInterval(()=>{if(arena.failed&&arena.event&&!arena.paused){arena.playTime=Math.min(CLIP_SECONDS*2,arena.playTime+.1*playbackSpeed);syncPresentation(arena.presentation());}if(auto&&view==='game'&&state?.match&&!modal.open&&!arena.isPlaying()&&!['SELECT','INPUT'].includes(document.activeElement?.tagName))step();},100);
try{data=await fetch(`${import.meta.env.BASE_URL}data/kangs.json`).then(r=>{if(!r.ok)throw Error('Data unavailable');return r.json();});try{const s=JSON.parse(localStorage.getItem(KEY));if(E.validSave(s))state=s;}catch{}view='landing';render();}catch(error){app.innerHTML=`<div class="error-screen"><h1>The program could not load.</h1><p>Please reload after your connection returns.</p><button onclick="location.reload()">Reload</button></div>`;}
// Check the same-origin published snapshot periodically; no third-party browser scraping.
setInterval(async()=>{try{const d=await fetch(`${import.meta.env.BASE_URL}data/kangs.json`,{cache:'no-store'}).then(r=>r.json());if(d.levels?.varsity?.players?.length)data=d;}catch{}},300000);

if(import.meta.env.PROD&&'serviceWorker' in navigator)navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js`).catch(error=>console.warn('Browser offline cache unavailable; local offline bundle remains supported.',error.message));

function setCamera(mode){arena.setView(mode);document.querySelectorAll('[data-camera]').forEach(b=>{b.classList.toggle('active',b.dataset.camera===mode);b.setAttribute('aria-pressed',b.dataset.camera===mode);});}
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey)return;const t=e.target;if(t.closest&&t.closest('input,select,textarea,[contenteditable]'))return;const k=e.key.toLowerCase();if((k===' '||k==='enter')&&t.closest&&t.closest('button,a,summary'))return;
 const rulesTab=modal.open?modal.querySelector('[data-rules-tab]'):null;if(rulesTab&&(k==='arrowright'||k==='arrowleft')){e.preventDefault();rules(+rulesTab.dataset.rulesTab+(k==='arrowright'?1:-1));return;}
 if(k==='h'||k==='?'){e.preventDefault();rules();return;}
 if(modal.open)return;
 const cams={'1':'broadcast','2':'court','3':'follow','4':'player'};if(cams[k]&&$('#arena')){e.preventDefault();setCamera(cams[k]);return;}
 const press=sel=>{const b=document.querySelector(sel);if(b&&!b.disabled){e.preventDefault();b.click();}};
 if(document.body.dataset.view==='game'){if(k===' ')press('[data-action="step"]');else if(k==='w')press('[data-action="auto"]');else if(k==='t')press('[data-action="timeout"]');}});

function cycleRoster(step){const list=state?.players||[];if(!list.length)return;const i=Math.max(0,list.findIndex(p=>p.id===rosterSel));rosterSel=list[(i+step+list.length)%list.length].id;render();document.querySelector(`.rv-arrow.${step>0?'next':'prev'}`)?.focus({preventScroll:true});}
document.addEventListener('keydown',e=>{if(document.body.dataset.view!=='roster'||modal.open||e.ctrlKey||e.metaKey||e.altKey)return;if(e.target.closest?.('input,select,textarea'))return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();cycleRoster(e.key==='ArrowRight'?1:-1);}});
document.addEventListener('click',e=>{const tr=e.target.closest?.('tr[data-select]');if(!tr||e.target.closest('input,button,a,select'))return;rosterSel=+tr.dataset.select;render();});
